/**
 * The names that the user code can use without a definition: the code
 * contract. code-runner.ts runs RUN_CONFIG, then processes.py, then
 * loader.py, then the user code, in one Python namespace.
 *
 * The Python files are the source. This file describes them for the linter
 * and the Code tab panel. test/algorithms/environment.test.ts checks that
 * the two stay in sync.
 */
import * as processesJson from './openeo-processes.json';

/**
 * The openEO process functions that processes.py exposes as bare names.
 * Generated by `pnpm processes:generate`.
 */
export const OPENEO_PROCESS_NAMES: readonly string[] = processesJson.processes;

export const OPENEO_CLIENT_VERSION: string = processesJson.openeoVersion;

const PYTHON_KEYWORDS = new Set(['and', 'or', 'not', 'if', 'in', 'is']);

// The OPENEO_PROCESS_NAMES contains the openEO processes as if they were used
// as bare: example max_, round_, if_. When using as part of the op. module,
// only names that are Python keywords (op.if_, op.and_) keep the
// underscore, therefore we must remove it from the others. max_ => op.max
export const OP_MEMBER_NAMES = OPENEO_PROCESS_NAMES.map((name) => {
  const base = name.replace(/_$/, '');
  return PYTHON_KEYWORDS.has(base) ? name : base;
});

/**
 * Every top-level name that code-runner.ts, processes.py and loader.py
 * define. The linter treats them as defined.
 */
export const LOADER_GLOBALS: readonly string[] = [
  // code-runner.ts
  'RUN_CONFIG',
  // processes.py
  'op',
  'process',
  // loader.py
  'json',
  'PGNode',
  'DataCube',
  'SaveResult',
  'Parameter',
  'default_collection_id',
  'default_bounding_box',
  'default_time',
  'default_bands',
  'default_cloud_cover_max',
  'bounding_box',
  'time',
  'bands',
  'cloud_cover_max',
  'parameters',
  'graph',
  'datacube',
  'map_graphs',
  'add_graph_to_map',
  'reduced'
];

export interface PublicGlobal {
  name: string;
  type: string;
  description: string;
}

